SELECT so.*, c.name AS customer_name, c.phone AS customer_phone, u.real_name AS operator_name
FROM sales_order so
LEFT JOIN customer c ON so.customer_id = c.id
LEFT JOIN sys_user u ON so.user_id = u.id


